#### 月票
[TUOJ](https://sim.csp.thusaac.com/contest/38/problem/3) 组合数学+暴力枚举
```cpp
const int MOD = 998244353;
int main() {
    int n, m;
    cin >> n >> m;
    vector<int> fixed(m);
    for (int i = 0; i < m; ++i) {
        cin >> fixed[i];
    }
    sort(fixed.begin(), fixed.end());
    // Precompute power of 26
    vector<long long> pow26(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        pow26[i] = (pow26[i - 1] * 26) % MOD;
    }
    long long ans = 0;
    // Enumerate all possible positions for "ccf" and "cspark"
    for (int i = 1; i <= n - 2; ++i) { // "ccf" starts at i (positions 1-based)
        // Check if "ccf" overlaps with any fixed '#'
        bool ccf_ok = true;
        for (int pos : {i, i + 1, i + 2}) {
            if (binary_search(fixed.begin(), fixed.end(), pos)) {
                ccf_ok = false;
                break;
            }
        }
        if (!ccf_ok) continue;
        for (int j = i + 3; j <= n - 5; ++j) { // "cspark" starts at j
            // Check if "cspark" overlaps with any fixed '#'
            bool cspark_ok = true;
            for (int pos : {j, j + 1, j + 2, j + 3, j + 4, j + 5}) {
                if (binary_search(fixed.begin(), fixed.end(), pos)) {
                    cspark_ok = false;
                    break;
                }
            }
            if (!cspark_ok) continue;
            // Calculate the number of free positions
            int free_pos = n - m - 3 - 6; // total free positions minus "ccf" and "cspark"
            ans = (ans + pow26[free_pos]) % MOD;
        }
    }
    cout << ans << endl;
    return 0;
}
```

